use std::{io::Write,process::{Command,Stdio},sync::{Arc,Barrier},thread};
fn main(){let barrier=Arc::new(Barrier::new(16));let mut joins=vec![];for t in 0..16{let b=barrier.clone();joins.push(thread::spawn(move||{b.wait();let mut ok=0;for n in 0..100{let mut child=Command::new("/bin/cat").env_clear().stdin(Stdio::piped()).stdout(Stdio::null()).stderr(Stdio::null()).spawn().unwrap();let original_pipe=child.stdin.take().unwrap();let mut pipe=std::fs::File::open("/dev/null").unwrap().try_clone().unwrap();let pid=child.id();child.kill().unwrap();let status=child.wait().unwrap();drop(original_pipe);let r=pipe.write_all(b"fixture completed frame\n").and_then(|_|pipe.flush());if r.is_ok(){ok+=1;println!("UNEXPECTED_WRITE_OK thread={t} n={n} killed_pid={pid} wait={status:?}");}}ok}));}let successes:usize=joins.into_iter().map(|j|j.join().unwrap()).sum();println!("completed 1600 killed-cat trials, successful_writes={successes}");}
